    int n; cin >> n;
    vector<int> a(n), b(n);
    for(int& i : a) cin >> i;
    for(int& i : b) cin >> i;
    LL res = 0;
    int c = 0;
    for(int i = 0; i < n; i ++)
    {
        if(a[i] != b[i])
        {
            c ++ ;
            res += c;
        }
        else{
            c = 0;
        } 
    }
    cout << res << "\n";
    return 0;
}

```




